class EventStore:
    def __init__(self):
        self.totals = {}
        self.applied_ids = set()

    def apply(self, event):
        key = event["account"]
        self.totals[key] = self.totals.get(key, 0) + event["amount"]
        self.applied_ids.add(event["id"])
        return True

