from minicode.importer import import_events

def retry_job(store, job):
    attempt = job["attempt"] + 1
    events = [{**event, "id": event["id"] + ":" + str(attempt)}
              for event in job["events"]]
    return {"attempt": attempt, **import_events(store, events)}

